import type { APIRequestContext } from "@playwright/test";

import { expect, test, uniqueName } from "../../fixtures";

const W9 = "Legal Name: Acme Supply\nTax ID: 123456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Supply\nEffective Date: 2025-01-01\nExpiry Date: 2099-12-31\n";
const insurance = (expiry: string) =>
  `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: 2000000\nExpiry Date: ${expiry}\n`;

async function inReviewVendor(member: APIRequestContext, insuranceText: string): Promise<string> {
  const create = await member.post("/api/vendors", {
    data: { name: uniqueName("Review"), category: "software", contact_email: "ops@northwind-supply.com" },
  });
  expect(create.status(), await create.text()).toBe(201);
  const vendor = await create.json();

  const uploads: [string, string, string][] = [
    ["w9", "w9.txt", W9],
    ["insurance_certificate", "insurance.txt", insuranceText],
    ["contract", "contract.txt", CONTRACT],
  ];
  for (const [kind, filename, text] of uploads) {
    const up = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind, file: { name: filename, mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(up.status(), await up.text()).toBe(201);
  }

  // Extraction runs in the background after each upload.
  await expect
    .poll(
      async () => {
        const r = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await r.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  return vendor.id as string;
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const lowVendorId = await inReviewVendor(member, insurance("next spring"));
  const highVendorId = await inReviewVendor(member, insurance("2099-12-31"));

  // Act
  const response = await reviewer.get("/api/review-queue");

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const queue = (await response.json()) as { vendor_id: string; lowest_confidence: number }[];
  // Other tests share the database, so compare only the two vendors this test created.
  const ours = queue.filter((item) => [lowVendorId, highVendorId].includes(item.vendor_id));
  expect(ours.map((item) => item.vendor_id)).toEqual([lowVendorId, highVendorId]);
  expect(ours[0].lowest_confidence).toBe(0.4);
});
